(()=>{const $=id=>document.getElementById(id);function ask(label,initial=""){return new Promise(resolve=>{const dialog=document.createElement('dialog'),form=document.createElement('form'),heading=document.createElement('h2'),input=document.createElement('textarea'),save=document.createElement('button'),cancel=document.createElement('button');heading.textContent=label;input.value=initial;input.required=true;input.maxLength=3000;input.setAttribute('aria-label',label);save.textContent='Continue';cancel.textContent='Cancel';cancel.type='button';const done=v=>{dialog.close();dialog.remove();resolve(v);};form.onsubmit=e=>{e.preventDefault();done(input.value.trim());};cancel.onclick=()=>done(null);dialog.oncancel=e=>{e.preventDefault();done(null);};form.append(heading,input,save,cancel);dialog.append(form);document.body.append(dialog);dialog.showModal();input.focus();});}let jobs=[],current,loadGeneration=0;const api=async (body,selected)=>{const r=await fetch('/api/studio/jobs'+(!body?'?archived='+($('job-show-archived').checked?'1':'0')+(selected?'&selected='+encodeURIComponent(selected):''):''),body?{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)}:{}),d=await r.json();if(!r.ok)throw Error(d.error);return d;};async function load(id){const generation=++loadGeneration;try{const snapshot=(await api(undefined,id)).jobs;if(generation!==loadGeneration)return false;jobs=snapshot;$('job-select').replaceChildren();if(id&&!jobs.some(j=>j.id===id)){current=undefined;$('job-actions').replaceChildren();$('job-brief').textContent='The selected job is unavailable in your account.';$('job-status').textContent='No other creative job was selected.';return false;}for(const j of jobs){const o=document.createElement('option');o.value=j.id;o.textContent=j.title+' · '+j.stage+(j.archived?' · Archived':'');$('job-select').append(o);}if(id&&jobs.some(j=>j.id===id))$('job-select').value=id;render();return true;}catch(e){if(generation!==loadGeneration)return false;if(id){current=undefined;$('job-select').replaceChildren();$('job-actions').replaceChildren();$('job-brief').textContent='The selected job could not be loaded.';}$('job-status').textContent=e.message;return false;}}function render(){$('job-actions').querySelectorAll('video,audio').forEach(media=>media.pause());current=jobs.find(j=>j.id===$('job-select').value);$('job-actions').replaceChildren();$('job-brief').textContent=current?current.brief+' · '+current.mediaIds.length+' saved assets'+(current.learning?' · Next action: '+current.learning:''):'Create a job or run your business workflow to begin.';if(!current)return;if(current.campaignNeedsReview){const notice=document.createElement('p');notice.textContent='Media changed. Review this job, choose its final media and review the linked campaign again.';$('job-actions').append(notice);}const assets=document.createElement('details'),summary=document.createElement('summary');summary.textContent='Review saved media & job history';assets.append(summary);window.addStudioMediaReview(assets,{...current},(id,target)=>change({action:'final-media',mediaId:id},target));for(const h of current.history||[]){const line=document.createElement('p');line.textContent=new Date(h.at).toLocaleString()+' · '+h.stage+' · '+h.note;assets.append(line);}$('job-actions').append(assets);if(current.campaignId||['Approved','Publish handoff'].includes(current.stage)){const handoff=document.createElement('button');handoff.textContent=current.campaignId?'Open linked campaign':'Create campaign from this job';handoff.onclick=async()=>{try{const result=current.campaignId?{campaignId:current.campaignId}:await api({action:'campaign',id:current.id,revision:current.revision});sessionStorage.setItem('bonga-open-campaign',result.campaignId);if(window.top===window)window.location.href='/fashion-service.html#social-campaigns';else{window.top.dispatchEvent(new CustomEvent('studio-campaign-open',{detail:result.campaignId}));window.top.location.hash='social-campaigns';}}catch(e){$('job-status').textContent=e.message;}};$('job-actions').append(handoff);}if(current.nextTaskId){const task=document.createElement('button');task.textContent='Open my follow-up task';task.onclick=()=>{if(window.top===window)window.location.href='/fashion-service.html#my-work';else{window.top.location.hash='my-work';window.top.location.reload();}};$('job-actions').append(task);}for(const [label,briefOnly] of [['Download project package',false],['Download brief only',true]]){const download=document.createElement('button');download.textContent=label;download.onclick=async()=>{const id=current.id;download.disabled=true;try{await window.downloadStudioPackage(id,briefOnly);}catch{}finally{download.disabled=false;}};$('job-actions').append(download);}const archive=document.createElement('button');archive.textContent=current.archived?'Restore project':'Archive project';archive.onclick=()=>change({action:'archive',archived:!current.archived});$('job-actions').append(archive);if(current.archived)return;if(['Brief','Creating','Review'].includes(current.stage)){const edit=document.createElement('button');edit.textContent='Edit title & brief';edit.onclick=async()=>{const target={...current};const title=await ask('Project title',target.title);if(title===null)return;const brief=await ask('Creative brief',target.brief);if(brief===null)return;await change({action:'edit',title,brief},target);};$('job-actions').append(edit);}const next={Brief:['Creating'],Creating:['Review'],Review:['Creating','Approved'],Approved:['Review','Publish handoff'],'Publish handoff':['Review']};for(const stage of next[current.stage]||[]){const b=document.createElement('button');b.textContent=stage==='Publish handoff'?'Prepare publishing handoff':'Move to '+stage;b.onclick=()=>change({action:'stage',stage});$('job-actions').append(b);}const attach=document.createElement('button');attach.textContent='Attach an existing file';attach.onclick=async()=>{const selectedJob=current.id;try{const r=await fetch('/api/designer/media'),d=await r.json();if(!r.ok)throw Error(d.error);const dialog=document.createElement('dialog'),close=document.createElement('button');close.textContent='Close';close.onclick=()=>dialog.remove();dialog.append(close);for(const f of d.files){const b=document.createElement('button');b.textContent=f.name;b.onclick=async()=>{try{await window.attachStudioMedia(f.id,selectedJob);dialog.remove();}catch(e){$('job-status').textContent=e.message;}};dialog.append(b);}document.body.append(dialog);dialog.showModal();}catch(e){$('job-status').textContent=e.message;}};$('job-actions').append(attach);if(current.stage==='Publish handoff'){const b=document.createElement('button');b.textContent='Record actual campaign results';b.onclick=async()=>{const target={...current};const source=await ask('Public post URL (after you publish manually)');if(!source)return;const values={};for(const k of ['views','enquiries','sales']){const v=await ask('Actual '+k+' count');if(v===null||v.trim()==='')return;values[k]=Number(v);}change({action:'measure',source,...values},target);};$('job-actions').append(b);$('job-status').textContent='Publishing authorization required. This handoff does not post automatically.';}}
async function change(body,target=current){if(!target)return;const id=target.id;try{if(body.action==='measure'&&window.top!==window&&!window.top.designerCloudReady?.())throw Error('Save or refresh your main dashboard records before recording results.');const result=await api({...body,id,revision:target.revision});if(result.workspaceChanged&&window.top!==window)window.top.dispatchEvent(new Event('studio-workspace-updated'));$('job-status').textContent=result.reviewRequired?'Saved. Review the changed media and linked campaign before approving again.':'Saved to Bonga Bhengu OS.';await load(current?.id||id);}catch(e){$('job-status').textContent=e.message;await load(current?.id||id);}}window.openStudioJob=async id=>{$('job-show-archived').checked=true;if(!await load(id))throw Error('The selected Studio job could not be opened.');$('creative-job-panel').scrollIntoView({behavior:'smooth'});};window.currentStudioJob=()=>current&&!current.archived?current.id:null;window.saveStudioProduction=async settings=>{if(!current)throw Error('Choose a creative job first.');const id=current.id;await api({action:'production',id,revision:current.revision,settings});await load(id);};window.loadStudioProduction=()=>current?.production||null;window.attachStudioMedia=async (mediaId,jobId)=>{const id=jobId||current?.id;if(!id)throw Error('File saved, but choose a creative job to attach it.');const snapshot=await api(undefined,id),target=snapshot.jobs.find(j=>j.id===id);if(!target)throw Error('The original creative job could not be found. File remains in your library.');await api({action:'attach',id,revision:target.revision,mediaId});await load(current?.id||id);};$('job-select').onchange=()=>{loadGeneration++;render();};$('job-show-archived').onchange=()=>load();$('job-route').onclick=async()=>{try{await api({action:'route'});await load();}catch(e){$('job-status').textContent=e.message;}};$('job-new').onclick=async()=>{const title=await ask('What are you creating?');if(!title)return;const brief=await ask('Audience, message and deliverable')||'';try{const j=await api({action:'create',title,brief});await load(j.id);}catch(e){$('job-status').textContent=e.message;}};const requestedJob=new URLSearchParams(location.search).get('job');if(requestedJob&&requestedJob.length<=200){$('job-show-archived').checked=true;load(requestedJob);}else load();})();